mapper.select:
SELECT , LEFT(n.notice_content, 1000) AS notice_content, nu.is_read, nu.read_time FROM sys_notice n INNER JOIN sys_notice_user nu ON nu.notice_id = n.notice_id AND nu.user_id = #{userId} LEFT JOIN sys_notice_type t ON t.notice_type_id = n.notice_type_id LEFT JOIN sys_user creator ON creator.user_id = n.create_by WHERE n.is_deleted = 0 AND n.status = 1
AND n.notice_title LIKE CONCAT('%', #{noticeTitle}, '%')
AND n.notice_type_id = #{noticeTypeId}
AND n.notice_level = #{noticeLevel}
AND nu.is_read = 0
ORDER BY n.is_top DESC, n.publish_time DESC, n.notice_id DESC

mapper.update:
UPDATE sys_notice
SET is_deleted = 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE notice_id = #{noticeId}
  AND is_deleted = 0

UPDATE sys_notice_user
SET is_read = 1,
    read_time = #{readTime}
WHERE user_id = #{userId}
  AND is_read = 0
  AND notice_id IN (
      SELECT notice_id FROM sys_notice WHERE status = 1 AND is_deleted = 0
  )
